# Build output with pattern: flip all T-shapes
# T-up: horizontal row of 3, pixel below center
# T-down: horizontal row of 3, pixel above center (center is the one above)

output_grid = [[0]*11 for _ in range(10)]

# Centers where shapes will be placed (flipped from input)
# Input had: 3 T-up (row 2,4,6) and 2 T-down (row 2,8)
# Output: 3 T-down and 2 T-up at same positions
centers = [(2, 2), (2, 8), (4, 3), (6, 7), (8, 2)]

# T-up: {(0,0), (0,1), (0,2), (1,1)} - row above, center below
# T-down: {(0,1), (1,0), (1,1), (1,2)} - center, row below

for r, ccenter in centers:
    # Determine shape type based on row position
    if r <= 2:
        # T-down at row 2, 4, 6
        shape = {(0, 1), (1, 0), (1, 1), (1, 2)}
    else:
        # T-up at row 8
        shape = {(0, 0), (0, 1), (0, 2), (1, 1)}

    # Actually, let me flip all: T-down becomes T-up and vice versa
    # Input: C0 (2,2)=T-down, C1 (2,8)=T-up, C2 (4,3)=T-up, C3 (6,7)=T-up, C4 (8,2)=T-down
    # Output: C0->T-up at (2,2), C1->T-down at (2,8), C2->T-down at (4,3), C3->T-down at (6,7), C4->T-up at (8,2)

    if r == 2 and ccenter == 2:
        # C0: T-down -> T-up
        shape = {(0, 0), (0, 1), (0, 2), (1, 1)}
    elif r == 8 and ccenter == 2:
        # C4: T-down -> T-up
        shape = {(0, 0), (0, 1), (0, 2), (1, 1)}
    else:
        # C1, C2, C3: T-up -> T-down
        shape = {(0, 1), (1, 0), (1, 1), (1, 2)}

    for dr, dc in shape:
        output_grid[r + dr][ccenter + dc] = 2

print("Output grid:")
for row in output_grid:
    print(' '.join(str(x) for x in row))

